7	/**
8	 * Derives an owner's {@code identityKey}, the single value used for duplicate detection. The
9	 * key is the full lower-case hex SHA-256 digest over
10	 * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. Two owners are duplicates
11	 * exactly when their identity keys are equal.
12	 *
13	 * <p>Kept out of {@link OwnerMapper} so MapStruct does not mistake its {@code String -> String}
14	 * methods for property mappings and apply them to every string property.
15	 */
16	public final class OwnerIdentity {
17	
18	    private OwnerIdentity() {
19	    }
20	
21	    /**
22	     * Builds the duplicate-detection identity key from an owner's normalized telephone, email
23	     * and last name. The email is trimmed and lower-cased and the last name is reduced to its
24	     * {@link #soundex soundex} code before hashing; a null telephone, email or last name
25	     * contributes an empty component. The result is the full lower-case hex SHA-256 of
26	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
27	     *
28	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
29	     * @param email               the owner's email, lower-cased here (may be {@code null})
30	     * @param lastName            the owner's last name, reduced to its soundex code (may be {@code null})
31	     * @return the 64-character lower-case hex identity key
32	     */
33	    public static String identityKey(String normalizedTelephone, String email, String lastName) {
34	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
35	        String lowerEmail = email == null ? "" : email.trim().toLowerCase();
36	        String source = telephone + "|" + lowerEmail + "|" + soundex(lastName);
37	        try {
38	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(source.getBytes(StandardCharsets.UTF_8));
39	            StringBuilder hex = new StringBuilder(digest.length * 2);
40	            for (byte b : digest) {
41	                hex.append(String.format("%02x", b));
42	            }
43	            return hex.toString();
44	        }
45	        catch (NoSuchAlgorithmException e) {
46	            throw new IllegalStateException("SHA-256 not available", e);
47	        }
48	    }
49	
50	    /**
51	     * Computes the American Soundex code of {@code name}: the upper-cased first letter followed
52	     * by three digits derived from the remaining consonants (vowels and the letters {@code h}
53	     * and {@code w} act as described by the standard algorithm), padded with zeros or truncated
54	     * to length four. Non-letters are ignored. Returns an empty string when {@code name} is null
55	     * or contains no letters.
56	     *
57	     * @param name the value to encode
58	     * @return the four-character soundex code, or an empty string when there is nothing to encode
59	     */
60	    public static String soundex(String name) {
61	        if (name == null) {
62	            return "";
63	        }
64	        StringBuilder letters = new StringBuilder();
65	        for (int i = 0; i < name.length(); i++) {
66	            char c = name.charAt(i);
67	            if (Character.isLetter(c)) {
68	                letters.append(Character.toUpperCase(c));
69	            }
70	        }
71	        if (letters.length() == 0) {
72	            return "";
73	        }
74	        StringBuilder code = new StringBuilder();
75	        code.append(letters.charAt(0));
76	        char previousDigit = digit(letters.charAt(0));
77	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
78	            char c = letters.charAt(i);
79	            // 'H' and 'W' are transparent: two consonants separated by them are treated as
80	            // adjacent, so the previous digit is carried across without being emitted again.
81	            if (c == 'H' || c == 'W') {
82	                continue;
83	            }
84	            char d = digit(c);
85	            if (d != '0' && d != previousDigit) {
86	                code.append(d);
87	            }
88	            // Vowels reset the previous digit to '0', so a repeated digit that a vowel separates
89	            // is emitted twice.
90	            previousDigit = d;
91	        }
92	        while (code.length() < 4) {
93	            code.append('0');
94	        }
95	        return code.toString();
96	    }
97	
98	    /**
99	     * Maps a letter to its soundex digit; vowels (and the transparent {@code h}/{@code w}) map
100	     * to {@code '0'}.
101	     */
102	    private static char digit(char c) {
103	        return switch (c) {
104	            case 'B', 'F', 'P', 'V' -> '1';
105	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
106	            case 'D', 'T' -> '3';
107	            case 'L' -> '4';
108	            case 'M', 'N' -> '5';
109	            case 'R' -> '6';
110	            default -> '0';
111	        };
112	    }
