15	 * by the controller), the controller sets {@code ownerSegment} once the level is known.
16	 */
17	public final class OwnerSegment {
18	
19	    /** The localities (regions) that count as METRO; anything else is REGIONAL. */
20	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
21	
