23	    }
24	
25	    /**
26	     * Compute the owner's segment from its membership level and locality.
27	     *
28	     * @param membershipLevel the owner's numeric membership level (1-4)
29	     * @param locality        the owner's locality (canonical region, or {@code "UNKNOWN"})
30	     * @return the segment formatted {@code '<TIER>_<AREA>'}
31	     */
32	    public static String segment(int membershipLevel, String locality) {
33	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
34	        String area = locality != null && METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
35	        return tier + "_" + area;
36	    }
