1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} (canonical region). The postcode is preferred: the
7	 * region is resolved by postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
8	 * and only falls back to the fixed city-to-region table when the postcode is absent or in
9	 * no known range. Kept out of {@link OwnerMapper} so MapStruct does not mistake it for a
10	 * {@code String -> String} mapping method and apply it to every string property.
11	 */
12	public final class OwnerLocality {
13	
14	    /** Fixed city-to-region table. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    /** Region -> inclusive 4-digit postcode range {low, high}. */
19	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
20	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
21	
22	    /** Fixed region -> IANA timezone table. */
23	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
24	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
25	
26	    private OwnerLocality() {
27	    }
28	
29	    /**
30	     * Return the canonical region for {@code city}, or {@code "UNKNOWN"} when the city is
31	     * null or not present in the table.
32	     */
33	    public static String forCity(String city) {
34	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
35	    }
36	
37	    /**
38	     * Return the canonical region, preferring the {@code postcode}: if it is a 4-digit code
39	     * that falls inside a known region's range, that region is returned; otherwise fall back
40	     * to the city-to-region table. Returns {@code "UNKNOWN"} when neither resolves a region.
41	     */
42	    public static String forCityAndPostcode(String city, String postcode) {
43	        String byPostcode = forPostcode(postcode);
44	        return byPostcode != null ? byPostcode : forCity(city);
45	    }
46	
47	    /**
48	     * Return the canonical region derived from the {@code postcode} alone (NSW 2000-2099,
49	     * VIC 3000-3099, QLD 4000-4099), or {@code "UNKNOWN"} when the postcode is absent,
50	     * malformed, or in no known range. This is the REGION component of an owner's
51	     * {@code memberId}.
52	     */
53	    public static String forPostcodeOrUnknown(String postcode) {
54	        String region = forPostcode(postcode);
55	        return region != null ? region : "UNKNOWN";
56	    }
57	
58	    /**
59	     * Return the REGION component of a {@code memberId} formatted
60	     * {@code '<REGION><FY><HASH8><CHK>'}, i.e. the leading run of letters before the two-digit
61	     * fiscal year. Returns {@code "UNKNOWN"} when the member id is null or carries no region
62	     * prefix. This is the owner's derived {@code locality}.
63	     */
64	    public static String regionFromMemberId(String memberId) {
65	        if (memberId == null) {
66	            return "UNKNOWN";
67	        }
68	        int i = 0;
69	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
70	            i++;
71	        }
72	        return i > 0 ? memberId.substring(0, i) : "UNKNOWN";
73	    }
74	
75	    /**
76	     * Return the IANA timezone name for the owner's {@code memberId}, derived from its
77	     * REGION component via the fixed region-to-timezone table (NSW -> Australia/Sydney,
78	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). Returns {@code null} when the
79	     * region is unknown, so the {@code timezone} field is omitted from the response.
80	     */
81	    public static String timezoneFromMemberId(String memberId) {
82	        return REGION_TIMEZONE.get(regionFromMemberId(memberId));
83	    }
84	
85	    /**
86	     * Compute the single Luhn check digit (0-9) over the digits contained in {@code s}.
