285	    /**
286	     * The owner's current primary identifier, as carried by the structured {@code OWNER_CREATED}
287	     * event. This is the owner's unified {@link Owner#getMemberId() memberId}.
288	     *
289	     * @param owner the newly created, saved owner
290	     * @return the owner's current primary identifier
291	     */
292	    private static String primaryIdentifier(Owner owner) {
293	        return owner.getMemberId();
294	    }
295	
296	    /**
297	     * Emits the immutable, structured {@code OWNER_CREATED} audit event via the {@code AUDIT}
298	     * logger, in addition to the human-readable audit line. The event is a JSON object
299	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}} where {@code seq}
300	     * is a process-wide monotonically increasing integer across creates, and the {@code memberId}
301	     * slot carries the owner's {@link #primaryIdentifier current primary identifier}.
302	     *
303	     * @param ownerId         the newly created owner's id
304	     * @param primaryId       the owner's current primary identifier (the memberId)
305	     * @param membershipLevel the owner's resolved membership level
306	     */
307	    private static void emitOwnerCreatedEvent(int ownerId, String primaryId, int membershipLevel) {
308	        long seq = AUDIT_EVENT_SEQ.incrementAndGet();
309	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},"
310	            + "\"event\":\"OWNER_CREATED\"}", seq, ownerId, primaryId, membershipLevel);
311	    }
312	
313	    /**
314	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
315	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
316	     * {@code null} (including when there is no active servlet request), so a missing or blank key
317	     * simply means "no idempotency" and the create proceeds normally.
318	     *
319	     * @return the current request's idempotency key, or {@code null} when none is supplied
320	     */
321	    private static String currentIdempotencyKey() {
322	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
323	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
324	            return null;
325	        }
326	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
327	        if (key == null || key.isBlank()) {
328	            return null;
329	        }
330	        return key.trim();
331	    }
