429	    /**
430	     * The maximum number of owners permitted per city. Owner creation is rejected once the
431	     * owner's city already contains this many owners.
432	     */
433	    private static final int MAX_OWNERS_PER_CITY = 50;
434	
435	    /**
436	     * Counts how many existing owners live in the given city, compared case-insensitively.
437	     * This is evaluated before the new owner is persisted, so the owner being created is not
438	     * included in the count.
439	     *
440	     * @param city the new owner's city
441	     * @return the number of existing owners in that city
442	     */
443	    private int countOwnersInCity(String city) {
444	        int count = 0;
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            if (city.equalsIgnoreCase(existing.getCity())) {
447	                count++;
448	            }
449	        }
450	        return count;
451	    }
452	
453	    /**
454	     * The number of owners in a city at or above which a capacity warning is raised. Once the
455	     * owner's city holds at least this many owners (but is still below {@link #MAX_OWNERS_PER_CITY},
456	     * the hard limit), the city is approaching capacity and {@code capacityWarning} is reported as
457	     * {@code true} in the owner response.
458	     */
459	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
460	
461	    /**
462	     * Reports whether the given city is approaching the per-city capacity limit, i.e. whether it
463	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} (40) and
464	     * {@link #MAX_OWNERS_PER_CITY} minus one (49) owners inclusive. At the hard limit of 50 the
465	     * create is rejected outright, so a full city never warns.
466	     *
467	     * @param city the owner's city
468	     * @return {@code true} when the city holds 40-49 owners, otherwise {@code false}
469	     */
470	    private boolean isApproachingCapacity(String city) {
471	        int count = countOwnersInCity(city);
472	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
473	    }
474	
475	    /**
476	     * The maximum number of owners that may be created in a single business day. Owner
477	     * creation is rejected once this many owners already fall on the new owner's adjusted
478	     * business day {@code registrationDate}.
479	     */
480	    private static final int MAX_OWNERS_PER_DAY = 100;
481	
482	    /**
483	     * The fixed list of public holidays that the business-day roll skips over. A date that
484	     * lands on one of these is rolled forward to the next non-holiday business day.
485	     */
486	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
487	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
488	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
489	        LocalDate.parse("2026-12-28"));
490	
491	    /**
492	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
493	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
494	     * while a date that is already a non-holiday weekday is returned unchanged.
495	     *
496	     * @param date the date to adjust
497	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
498	     */
499	    private LocalDate toBusinessDay(LocalDate date) {
500	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
501	                || PUBLIC_HOLIDAYS.contains(date)) {
502	            date = date.plusDays(1);
503	        }
504	        return date;
505	    }
506	
507	    /**
508	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
509	     * registrationDate} rolls forward to the same business day. This is evaluated before the
510	     * new owner is persisted, so the owner being created is not included in the count.
511	     *
512	     * @param businessDay the adjusted business day to count against
513	     * @return the number of existing owners registered on that business day
514	     */
515	    private int countOwnersRegisteredOn(LocalDate businessDay) {
516	        int count = 0;
517	        for (Owner existing : this.clinicService.findAllOwners()) {
518	            LocalDate existingDate = existing.getRegistrationDate();
519	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
520	                count++;
521	            }
522	        }
523	        return count;
524	    }
525	
526	    /**
527	     * The number of owners that may be created on a single business day before a bulk-signup
528	     * warning is raised. Once more than this many owners already fall on the current business
529	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
530	     */
531	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
532	
533	    /**
534	     * Reports whether an unusually high number of owners have been created for today's business
535	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
536	     * the business day that {@code LocalDate.now()} rolls forward to.
537	     *
538	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
539	     */
540	    private boolean isBulkSignupDay() {
541	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
542	    }
