544	    /**
545	     * Builds the unified member id for a newly created owner, formatted
546	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the canonical region
547	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
548	     * {@code "UNKNOWN"} when the postcode resolves no region), {@code FY} is the last two
549	     * digits of the fiscal year of the business-day-adjusted registration date (fiscal year
550	     * starts 1 July, named by the year it ends in), {@code HASH8} is the first eight
551	     * upper-case hex characters of the SHA-256 digest of {@code normalizedTelephone + lastName}
552	     * (the same hash used by the region-and-hash identity), and {@code CHK} is a single Luhn
553	     * check digit computed over the digits of {@code '<REGION><FY><HASH8>'}. The id carries no
554	     * sequence number, so it is stable for a given telephone, last name and fiscal year rather
555	     * than dependent on creation order.
556	     *
557	     * @param postcode            the owner's postcode (may be {@code null})
558	     * @param normalizedTelephone the owner's normalized E.164 telephone
559	     * @param lastName            the owner's last name
560	     * @param registrationDate    the owner's business-day-adjusted registration date
561	     * @return the assigned member id (e.g. {@code 'NSW271A2B3C4D5'})
562	     */
563	    private static String memberId(String postcode, String normalizedTelephone, String lastName,
564	        LocalDate registrationDate) {
565	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
566	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
567	        String fy = String.format("%02d", Math.floorMod(fiscalYear, 100));
568	        String base = region + fy + sha256Hex8(normalizedTelephone + lastName);
569	        int chk = org.springframework.samples.petclinic.mapper.OwnerLocality.luhn(base);
570	        return base + chk;
571	    }
