573	    /**
574	     * De-duplicates a freshly computed {@code base} member id against the ids already
575	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
576	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
577	     * yields an id no existing owner holds.
578	     *
579	     * @param base the computed {@code '<REGION><FY><HASH8><CHK>'} member id
580	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
581	     */
582	    private String deduplicatedMemberId(String base) {
583	        Set<String> existing = new HashSet<>();
584	        for (Owner owner : this.clinicService.findAllOwners()) {
585	            if (owner.getMemberId() != null) {
586	                existing.add(owner.getMemberId());
587	            }
588	        }
589	        if (!existing.contains(base)) {
590	            return base;
591	        }
592	        int n = 2;
593	        while (existing.contains(base + "-" + n)) {
594	            n++;
595	        }
596	        return base + "-" + n;
597	    }
