599	    /**
600	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
601	     * bytes of {@code source} — the {@code HASH8} component of an owner's member id.
602	     *
603	     * @param source the string to hash
604	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
605	     */
606	    private static String sha256Hex8(String source) {
607	        try {
608	            byte[] digest = MessageDigest.getInstance("SHA-256")
609	                .digest(source.getBytes(StandardCharsets.UTF_8));
610	            StringBuilder hex = new StringBuilder(digest.length * 2);
611	            for (byte b : digest) {
612	                hex.append(String.format("%02x", b));
613	            }
614	            return hex.substring(0, 8).toUpperCase();
615	        } catch (NoSuchAlgorithmException e) {
616	            throw new IllegalStateException("SHA-256 not available", e);
617	        }
618	    }
