626	     * @param lastName  the new owner's last name
627	     * @return the number of existing owners with the same first and last name
628	     */
629	    private int countNamesakes(String firstName, String lastName) {
630	        int count = 0;
631	        for (Owner existing : this.clinicService.findAllOwners()) {
632	            if (firstName.equalsIgnoreCase(existing.getFirstName())
633	                && lastName.equalsIgnoreCase(existing.getLastName())) {
