640	    /**
641	     * Canonical expansions applied to common street-type abbreviations during address
642	     * normalization. Keys and values are upper-cased so the lookup runs after the address
643	     * has itself been upper-cased.
644	     */
645	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
646	        "ST", "STREET",
647	        "RD", "ROAD",
648	        "AVE", "AVENUE");
649	
650	    /**
651	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
652	     * every run of internal whitespace is collapsed to a single space, the result is
653	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
654	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
655	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
656	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
657	     * returned and compared for household duplicates; an address that is blank once
658	     * normalized fails the required-field check.
659	     *
660	     * @param address the raw address value supplied by the client
661	     * @return the normalized address (empty string when {@code address} is null or blank)
662	     */
663	    /**
664	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
665	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
666	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
667	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
668	     * address returned is the normalized {@code addressLine1} with a single space and the
669	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
670	     * the flat {@code address} is normalized and returned, and the structured lines are left
671	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
672	     * downstream (household hash, postcode validation and locality); an owner that supplies
673	     * neither form yields an empty string, failing the required-address check.
674	     *
675	     * @param owner          the owner being created, whose structured address lines are set here
676	     * @param ownerFieldsDto the submitted owner fields
677	     * @return the composed, normalized address (empty string when no address form is supplied)
678	     */
679	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
680	        String addressLine1 = ownerFieldsDto.getAddressLine1();
681	        if (addressLine1 != null && !addressLine1.isBlank()) {
682	            String normalizedLine1 = normalizeAddress(addressLine1);
683	            owner.setAddressLine1(normalizedLine1);
684	            String addressLine2 = ownerFieldsDto.getAddressLine2();
685	            if (addressLine2 != null && !addressLine2.isBlank()) {
686	                String normalizedLine2 = normalizeAddress(addressLine2);
687	                owner.setAddressLine2(normalizedLine2);
688	                return normalizedLine1 + " " + normalizedLine2;
689	            }
690	            owner.setAddressLine2(null);
691	            return normalizedLine1;
692	        }
693	        owner.setAddressLine1(null);
694	        owner.setAddressLine2(null);
695	        return normalizeAddress(ownerFieldsDto.getAddress());
696	    }
697	
698	    private static String normalizeAddress(String address) {
699	        if (address == null) {
700	            return "";
701	        }
702	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
703	        if (collapsed.isEmpty()) {
704	            return "";
705	        }
706	        StringBuilder normalized = new StringBuilder(collapsed.length());
707	        for (String token : collapsed.split(" ")) {
708	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
709	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
710	            if (normalized.length() > 0) {
711	                normalized.append(' ');
712	            }
713	            normalized.append(expanded != null ? expanded : token);
714	        }
715	        return normalized.toString();
716	    }
