718	    /**
719	     * Normalizes a last name or address for household-duplicate comparison: leading and
720	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
721	     * single space and the result is lower-cased. Two owners are considered to share a
722	     * household when both their last names and addresses produce the same key.
723	     *
724	     * @param value the raw last name or address value
725	     * @return the normalized comparison key (empty string when {@code value} is null)
726	     */
727	    private static String householdKey(String value) {
728	        if (value == null) {
729	            return "";
730	        }
731	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
732	    }
