734	    /**
735	     * Derives the stable shared household identifier for the given normalized last name key
736	     * and postcode. The identifier is deterministic — the same household (same
737	     * {@link #householdKey normalized} last name and postcode) always maps to the same
738	     * value — so every owner in a household is assigned an identical id. It is the
739	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
740	     * '<lastNameKey>|<postcode>'}.
741	     *
742	     * @param lastNameKey the normalized last name key
743	     * @param postcode    the owner's postcode
744	     * @return the shared household identifier
745	     */
746	    private static String householdId(String lastNameKey, String postcode) {
747	        String source = lastNameKey + "|" + postcode;
748	        try {
749	            byte[] digest = MessageDigest.getInstance("SHA-256")
750	                .digest(source.getBytes(StandardCharsets.UTF_8));
751	            StringBuilder hex = new StringBuilder(digest.length * 2);
752	            for (byte b : digest) {
753	                hex.append(String.format("%02x", b));
754	            }
755	            return hex.substring(0, 12).toUpperCase();
756	        } catch (NoSuchAlgorithmException e) {
757	            throw new IllegalStateException("SHA-256 not available", e);
758	        }
759	    }
