761	    /**
762	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
763	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
764	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
765	     * collides with a computed household id.
766	     *
767	     * @param owner the existing owner
768	     * @return the owner's household id, or {@code null} when it has no postcode
769	     */
770	    private static String computeHouseholdId(Owner owner) {
771	        if (owner.getPostcode() == null) {
772	            return null;
773	        }
774	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
775	    }
