777	    /**
778	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
779	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
780	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
781	     * when mapping a collection to size every household from a single scan.
782	     *
783	     * @param ownerDto the dto to populate
784	     * @param owner    the owner being mapped
785	     */
786	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
787	        applyMembership(ownerDto, owner, householdSizes());
