790	    /**
791	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
792	     * dto using a pre-computed map of household id to member count.
793	     *
794	     * @param ownerDto       the dto to populate
795	     * @param owner          the owner being mapped
796	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
797	     */
798	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
799	        int householdSize = owner.getHouseholdId() == null ? 1
800	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
801	        int points = MembershipPoints.points(owner, householdSize);
802	        ownerDto.setMembershipPoints(points);
803	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
804	        applyOwnerSegment(ownerDto);
805	    }
