807	    /**
808	     * Populates an owner's {@code ownerSegment} on the given dto from its already-applied
809	     * {@code membershipLevel} and mapped {@code locality}. Call this whenever the membership
810	     * level changes (e.g. after {@link #capMembershipLevelToHousehold}) so the segment stays
811	     * consistent with the level.
812	     *
813	     * @param ownerDto the dto whose membershipLevel and locality are already populated
814	     */
815	    private void applyOwnerSegment(OwnerDto ownerDto) {
816	        Integer membershipLevel = ownerDto.getMembershipLevel();
817	        int level = membershipLevel == null ? 1 : membershipLevel;
818	        ownerDto.setOwnerSegment(org.springframework.samples.petclinic.mapper.OwnerSegment.segment(
819	            level, ownerDto.getLocality()));
