822	    /**
823	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
824	     * {@code membershipLevel} among the other current members of its household, writing the
825	     * capped value back onto the dto and returning it. A member's current level is scored the
826	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
827	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
828	     * has no household, or is the only member of its household, no cap applies and the level is
829	     * returned unchanged.
830	     *
831	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
832	     * @param owner          the newly created owner (already saved, so it has an id)
833	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
834	     * @return the resulting (possibly capped) membership level
835	     */
836	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
837	        Map<String, Integer> householdSizes) {
838	        int level = ownerDto.getMembershipLevel();
839	        String householdId = owner.getHouseholdId();
840	        if (householdId == null) {
841	            return level;
842	        }
843	        Integer maxMemberLevel = null;
844	        for (Owner existing : this.clinicService.findAllOwners()) {
845	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
846	                continue;
847	            }
848	            if (householdId.equals(existing.getHouseholdId())) {
849	                int size = householdSizes.getOrDefault(householdId, 1);
850	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
851	                maxMemberLevel = maxMemberLevel == null ? memberLevel
852	                    : Math.max(maxMemberLevel, memberLevel);
853	            }
854	        }
855	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
856	            level = maxMemberLevel + 1;
857	            ownerDto.setMembershipLevel(level);
858	        }
859	        return level;
860	    }
