862	    /**
863	     * Counts how many owners belong to each household, keyed by household id. Owners without a
864	     * household id (no postcode) are excluded — such an owner is its own single-member household.
865	     *
866	     * @return a map from household id to the number of owners sharing it
867	     */
868	    private Map<String, Integer> householdSizes() {
869	        Map<String, Integer> sizes = new java.util.HashMap<>();
870	        for (Owner existing : this.clinicService.findAllOwners()) {
871	            String householdId = existing.getHouseholdId();
872	            if (householdId != null) {
873	                sizes.merge(householdId, 1, Integer::sum);
874	            }
875	        }
876	        return sizes;
877	    }
