879	    /**
880	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
881	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
882	     * possible duplicate when a non-deleted existing owner shares its {@link
883	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
884	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
885	     * Because the telephone is part of the identity key, two owners with the same last name and
886	     * postcode but different telephones differ in their keys and so surface here as a soft match
887	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
888	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
889	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
890	     * matching id is recorded.
891	     *
892	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
893	     */
894	    private void applyPossibleDuplicate(Owner owner) {
895	        owner.setPossibleDuplicate(false);
896	        if (owner.getPostcode() == null) {
897	            return;
898	        }
899	        String soundex = OwnerIdentity.soundex(owner.getLastName());
900	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
901	        Owner match = null;
902	        for (Owner existing : this.clinicService.findAllOwners()) {
903	            if (existing.isDeleted()) {
904	                continue;
905	            }
906	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
907	                && owner.getPostcode().equals(existing.getPostcode())
908	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
909	                    existing.getEmail(), existing.getLastName()))) {
910	                if (match == null || (existing.getId() != null
911	                    && existing.getId() < match.getId())) {
912	                    match = existing;
913	                }
914	            }
915	        }
916	        if (match != null) {
917	            owner.setPossibleDuplicate(true);
918	            owner.setPossibleDuplicateOf(match.getId());
919	        }
920	    }
