922	    /**
923	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
924	     * and brackets are stripped. When the number already carries a leading {@code '+'}
925	     * and country code these are kept; a number written in national trunk form (a leading
926	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
927	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
928	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
929	     * after the {@code '+'}, and its national-number length must be valid for the detected
930	     * country code (see {@link #hasValidNationalLength}).
931	     *
932	     * @param telephone the raw telephone value supplied by the client
933	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
934	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
935	     */
936	    private static String toE164(String telephone) {
937	        if (telephone == null) {
938	            return null;
939	        }
940	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
941	        String digits;
942	        if (cleaned.startsWith("+")) {
943	            digits = cleaned.substring(1);
944	        } else if (cleaned.startsWith("0")) {
945	            digits = "61" + cleaned.substring(1);
946	        } else {
947	            digits = "1" + cleaned;
948	        }
949	        if (!digits.matches("[0-9]{8,15}")) {
950	            return null;
951	        }
952	        if (!hasValidNationalLength(digits)) {
953	            return null;
954	        }
955	        return "+" + digits;
956	    }
957	
958	    /**
959	     * Validates the national-number length of an E.164 digit string against its country
960	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
961	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
962	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
963	     *
964	     * @param digits the E.164 digits (without the leading {@code '+'})
965	     * @return {@code true} when the national-number length is valid for the country code
966	     */
967	    private static boolean hasValidNationalLength(String digits) {
968	        if (digits.startsWith("61")) {
969	            return digits.length() - 2 == 9;
970	        }
971	        if (digits.startsWith("1")) {
972	            return digits.length() - 1 == 10;
973	        }
974	        return true;
975	    }
