977	    /**
978	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
979	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
980	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
981	     */
982	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
983	        "NSW", new int[] {2000, 2099},
984	        "VIC", new int[] {3000, 3099},
985	        "QLD", new int[] {4000, 4099});
