987	    /**
988	     * Validates an owner's postcode for creation. A postcode is only ever validated when
989	     * present (an absent postcode is optional and accepted). When present it must be exactly
990	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
991	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
992	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
993	     *
994	     * @param postcode the supplied postcode (never {@code null} here)
995	     * @param city     the owner's city, used to derive the region
996	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
997	     *         (signalling a 400 Bad Request)
998	     */
999	    private static boolean isValidPostcode(String postcode, String city) {
1000	        if (!postcode.matches("[0-9]{4}")) {
1001	            return false;
1002	        }
1003	        int[] range = REGION_POSTCODES.get(
1004	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
1005	        if (range == null) {
1006	            return true;
1007	        }
1008	        int value = Integer.parseInt(postcode);
1009	        return value >= range[0] && value <= range[1];
1010	    }
