1013	     * Disposable email domains that are not accepted for owner creation. An owner whose
1014	     * email domain (compared case-insensitively) is in this set is rejected with a 400
1015	     * Bad Request.
1016	     */
1017	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
1018	        "mailinator.com", "tempmail.com", "guerrillamail.com");
