1020	    /**
1021	     * Normalizes an owner email for creation. A present email must be a syntactically
1022	     * valid address whose domain is not on the disposable-domain blocklist ({@link
1023	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
1024	     *
1025	     * @param email the raw email value supplied by the client (never {@code null} here)
1026	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
1027	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
1028	     */
1029	    private static String normalizeEmail(String email) {
1030	        String trimmed = email.trim();
1031	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
1032	            return null;
1033	        }
1034	        String normalized = trimmed.toLowerCase();
1035	        String domain = normalized.substring(normalized.indexOf('@') + 1);
1036	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
1037	            return null;
1038	        }
1039	        return normalized;
1040	    }
