1042	    /**
1043	     * Reports whether an owner should be flagged for manual review. The flag is raised when
1044	     * <em>any</em> of three risk signals hold and is otherwise {@code false}:
1045	     * <ul>
1046	     *   <li>the owner is a {@link Owner#getPossibleDuplicate() possible duplicate};</li>
1047	     *   <li>its email domain is {@link #isDisposableAdjacentEmail disposable-adjacent};</li>
1048	     *   <li>its city is {@link #isOverSoftCapacity over its soft capacity}.</li>
1049	     * </ul>
1050	     *
1051	     * @param owner the owner whose risk flag is being computed
1052	     * @return {@code true} when any risk signal holds, otherwise {@code false}
1053	     */
1054	    private boolean isRiskFlag(Owner owner) {
1055	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
1056	            || isDisposableAdjacentEmail(owner.getEmail())
1057	            || isOverSoftCapacity(owner.getCity());
1058	    }
