1060	    /**
1061	     * Reports whether an email address's domain is "disposable-adjacent" — either exactly one of
1062	     * the known {@link #DISPOSABLE_EMAIL_DOMAINS disposable domains}, a subdomain of one, or a
1063	     * domain sharing its second-level label with one (e.g. {@code mailinator.com} is disposable,
1064	     * so {@code mailinator.net} and {@code mail.mailinator.io} are disposable-adjacent). An exact
1065	     * disposable domain is itself rejected at creation, so this widens the net to the near-miss
1066	     * domains that a create otherwise accepts. A {@code null} email is never disposable-adjacent.
1067	     *
1068	     * @param email the owner's stored (already lower-cased) email, or {@code null}
1069	     * @return {@code true} when the email's domain is disposable-adjacent
1070	     */
1071	    private static boolean isDisposableAdjacentEmail(String email) {
1072	        if (email == null) {
1073	            return false;
1074	        }
1075	        int at = email.lastIndexOf('@');
1076	        if (at < 0 || at == email.length() - 1) {
1077	            return false;
1078	        }
1079	        String domain = email.substring(at + 1).toLowerCase();
1080	        String domainLabel = secondLevelLabel(domain);
1081	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
1082	            if (domain.equals(disposable) || domain.endsWith("." + disposable)) {
1083	                return true;
1084	            }
1085	            if (!domainLabel.isEmpty() && domainLabel.equals(secondLevelLabel(disposable))) {
1086	                return true;
1087	            }
1088	        }
1089	        return false;
1090	    }
1091	
1092	    /**
1093	     * Returns the second-level label of a domain: the label immediately to the left of the
1094	     * top-level domain (e.g. {@code "mailinator"} for both {@code "mailinator.com"} and
1095	     * {@code "mail.mailinator.io"}). A domain with no dot is returned unchanged.
1096	     *
1097	     * @param domain the lower-cased domain
1098	     * @return the second-level label
1099	     */
1100	    private static String secondLevelLabel(String domain) {
1101	        int lastDot = domain.lastIndexOf('.');
1102	        if (lastDot < 0) {
1103	            return domain;
1104	        }
1105	        String withoutTld = domain.substring(0, lastDot);
1106	        int prevDot = withoutTld.lastIndexOf('.');
1107	        return prevDot < 0 ? withoutTld : withoutTld.substring(prevDot + 1);
1108	    }
1109	
1110	    /**
1111	     * Reports whether a city is over its soft capacity, i.e. already holds at least
1112	     * {@link #CAPACITY_WARNING_THRESHOLD} owners (the same threshold that raises the
1113	     * {@code capacityWarning}). Unlike {@link #isApproachingCapacity} this is not bounded below
1114	     * the hard {@link #MAX_OWNERS_PER_CITY} limit, so a city sitting exactly at the hard limit
1115	     * still counts as over its soft capacity.
1116	     *
1117	     * @param city the owner's city
1118	     * @return {@code true} when the city holds at least {@link #CAPACITY_WARNING_THRESHOLD} owners
1119	     */
1120	    private boolean isOverSoftCapacity(String city) {
1121	        return countOwnersInCity(city) >= CAPACITY_WARNING_THRESHOLD;
1122	    }
1123	}
